    const yes=el("button","btn primary","نعم، أعد الفتح");yes.type="button";yes.dataset.act="reopen-yes";const no=el("button","btn","لا");no.type="button";
    no.onclick=()=>{d.querySelector("#reopenBox")&&d.querySelector("#reopenBox").remove();addReopen(d,st,id);};
